<template><section class="permits"><div class="heading"><strong>工艺跳步许可配置</strong><el-select v-model="itemId" placeholder="选择工单产品明细" :disabled="busy" @change="load"><el-option v-for="(item,index) in items" :key="item.id" :value="item.id" :label="`${item.snapshot?.name??'产品'} ${index+1}`"/></el-select><el-button :disabled="loading||busy||!itemId||plans.length<3||failed" @click="create">新增许可</el-button><el-button :disabled="loading||busy||!itemId" @click="load">刷新</el-button></div><p>许可按产品、规格和完整路线适用，仅支持本工单同明细跳步。跳过不产生报工，带跳步轨迹的余量不作为跨工单完整路线释放。</p><p v-if="itemId&&plans.length<3" role="status">当前路线不足三道工序，无需配置跳步许可。</p><el-alert v-if="failed" title="工艺许可加载失败，请重试" type="error" :closable="false"/><div class="scroll"><el-table :data="rows" v-loading="loading" border><el-table-column label="来源已完成工序" min-width="170"><template #default="{row}">{{stepName(row.sourceSequence)}}</template></el-table-column><el-table-column label="允许进入工序" min-width="170"><template #default="{row}">{{stepName(row.targetSequence)}}</template></el-table-column><el-table-column label="状态" min-width="100"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column prop="version" label="版本" width="80"/><el-table-column prop="reason" label="配置原因" min-width="180"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button :disabled="busy" link type="primary" @click="edit(row)">修改</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="工艺跳步许可" width="min(650px,96vw)" append-to-body :show-close="!busy" :close-on-click-modal="false" :close-on-press-escape="!busy" :before-close="done=>{if(!busy)done()}"><el-form ref="permitForm" :model="draft" :rules="rules" scroll-to-error :disabled="busy" label-width="120px"><el-form-item label="来源工序" prop="sourceSequence" required><el-select v-model="draft.sourceSequence" placeholder="请选择来源工序" @change="sourceChanged"><el-option v-for="(step,index) in plans" :key="step.processId" :label="stepName(index+1)" :value="index+1" :disabled="index+3>plans.length"/></el-select></el-form-item><el-form-item label="目标工序" prop="targetSequence" required><el-select v-model="draft.targetSequence" placeholder="请选择至少跨过一道的目标工序"><el-option v-for="(step,index) in plans" :key="step.processId" :label="stepName(index+1)" :value="index+1" :disabled="index+1<=draft.sourceSequence+1"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="draft.enabled"/></el-form-item><el-form-item label="原因" prop="reason" required><el-input v-model="draft.reason" type="textarea" maxlength="500" show-word-limit/></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存许可</el-button></template></el-dialog></section></template>
<script setup lang="ts">
import type {FormInstance,FormRules} from 'element-plus';import {fieldRule,textRules,applyFieldErrors} from '@/utils/input-validation';import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';import {ElMessage} from 'element-plus';import request from '@/utils/request';import {createUUID} from '@/utils/uuid';type R=Record<string,any>;const props=defineProps<{workOrderId:string;items:R[]}>(),itemId=ref(''),rows=ref<R[]>([]),loading=ref(false),failed=ref(false),busy=ref(false),visible=ref(false),draft=reactive<R>({}),plans=computed(()=>props.items.find(i=>i.id===itemId.value)?.plans??[]);let epoch=0,disposed=false
const permitForm=ref<FormInstance>()
const rules:FormRules={sourceSequence:[fieldRule(v=>Number.isInteger(v)&&Number(v)>=1&&Number(v)<=plans.value.length-2?'':'请选择具有可跳目标的来源工序','change')],targetSequence:[fieldRule(v=>Number.isInteger(v)&&Number(v)>draft.sourceSequence+1&&Number(v)<=plans.value.length?'':'目标工序必须至少跨过一道工序','change')],reason:textRules('配置原因',500,true)}
function sourceChanged(){if(draft.targetSequence<=draft.sourceSequence+1)draft.targetSequence=undefined;permitForm.value?.clearValidate('targetSequence')}
function stepName(seq:number){return `第${seq}道·${plans.value[seq-1]?.processName??'工序'}`}
async function load(){const ticket=++epoch,work=props.workOrderId,item=itemId.value,current=()=>!disposed&&ticket===epoch&&work===props.workOrderId&&item===itemId.value;rows.value=[];visible.value=false;if(!item)return;loading.value=true;failed.value=false;try{const r:any=await request({url:'/metal/route-skip-permits',params:{itemId:item},isContextCurrent:current});if(current())rows.value=r.data}catch{if(current())failed.value=true}finally{if(current())loading.value=false}}
function create(){if(plans.value.length<3||failed.value)return;permitForm.value?.clearValidate();Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,{sourceSequence:1,targetSequence:3,enabled:true,reason:'',requestId:createUUID()});visible.value=true}function edit(row:R){permitForm.value?.clearValidate();Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,row,{requestId:createUUID(),reason:''});visible.value=true}
async function save(){if(busy.value||!visible.value)return;const session=epoch,itemAtStart=itemId.value,draftRequest=draft.requestId;if(!await permitForm.value?.validate().catch(()=>false)||!visible.value||session!==epoch||itemAtStart!==itemId.value||draftRequest!==draft.requestId)return;busy.value=true;const ticket=epoch,work=props.workOrderId,item=itemId.value,body=JSON.parse(JSON.stringify({...draft,reason:draft.reason.trim(),itemId:item})),current=()=>!disposed&&ticket===epoch&&work===props.workOrderId&&item===itemId.value;try{await request({url:'/metal/route-skip-permits'+(body.permitId?'/'+body.permitId:''),method:body.permitId?'put':'post',data:body,isContextCurrent:current});if(current()){visible.value=false;ElMessage.success('工艺许可已保存');await load()}}catch(error){if(current())applyFieldErrors(permitForm.value,error)}finally{if(!disposed)busy.value=false}}
watch(()=>props.workOrderId,()=>{epoch++;itemId.value=props.items[0]?.id??'';void load()},{immediate:true});watch(()=>props.items,()=>{if(!props.items.some(i=>i.id===itemId.value)){itemId.value=props.items[0]?.id??'';void load()}});onBeforeUnmount(()=>{disposed=true;epoch++})
</script><style scoped>.permits{margin-top:16px;padding:16px;background:#fff;border:1px solid #e4e7ed;border-radius:10px;min-width:0}.heading{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.heading .el-select{width:250px}p{font-size:13px;color:#667085;line-height:1.7}.scroll{max-width:100%;overflow-x:auto}@media(max-width:480px){.permits{padding:10px}.heading .el-select{width:100%}}</style>
